#!/usr/bin/env python3
"""Generates config/world.yaml, the scene simulated by sim_lidar.

The scene is an aircraft hangar with an airplane inside and a few test shapes that exercise
plane constraints. Edit build_hangar_world() and re-run this script to regenerate the file.

Usage: create_world.py [output_path]
"""

import math
import os
import sys

import yaml

HEADER = """\
# World simulated by sim_lidar, generated by scripts/create_world.py.
#
# Every object is one geometric primitive:
#   plane      infinite plane through `center`, normal along the local z axis
#   sphere     sphere of `radius`
#   cylinder   infinite cylinder of `radius`, axis along the local z axis
#   cone       double cone x^2 + y^2 = slope^2 * z^2, axis along the local z axis
#   ellipsoid  semi-axes `size` along the local x, y and z axes
# `center` [m] and `angles` (roll, pitch, yaw [rad], applied as Rz(yaw) * Ry(pitch) * Rx(roll))
# place the local frame in the world; `angles` defaults to zero.
#
# `plane_constraints` cut away part of a primitive: a surface point p, expressed in the
# primitive's local frame, is kept only if normal . (p - point) > 0 for every constraint.
"""


def constraint(normal, point):
    """Plane constraint keeping the side of the plane the normal points to."""
    return {'normal': list(normal), 'point': list(point)}


class WorldBuilder:
    """Accumulates primitives and writes them in the format read by sim_lidar."""

    def __init__(self):
        self.objects = []

    def add_plane(self, center, angles, plane_constraints=(), description=''):
        self._add('plane', description, plane_constraints, center=center, angles=angles)

    def add_sphere(self, center, radius, plane_constraints=(), description=''):
        self._add('sphere', description, plane_constraints, center=center, radius=radius)

    def add_cylinder(self, center, angles, radius, plane_constraints=(), description=''):
        self._add('cylinder', description, plane_constraints,
                  center=center, angles=angles, radius=radius)

    def add_cone(self, center, angles, slope, plane_constraints=(), description=''):
        self._add('cone', description, plane_constraints,
                  center=center, angles=angles, slope=slope)

    def add_ellipsoid(self, center, size, angles=(0, 0, 0), plane_constraints=(), description=''):
        if len(size) != 3:
            raise ValueError(f'Ellipsoid "{description}" needs 3 semi-axes, got {size}')
        self._add('ellipsoid', description, plane_constraints,
                  center=center, size=size, angles=angles)

    def save(self, path):
        with open(path, 'w') as file:
            file.write(HEADER)
            yaml.safe_dump({'objects': self.objects}, file,
                           default_flow_style=None, sort_keys=False, width=100)

    def _add(self, primitive_type, description, plane_constraints, **fields):
        obj = {'type': primitive_type, 'description': description}
        for key, value in fields.items():
            obj[key] = list(value) if isinstance(value, (list, tuple)) else value
        if plane_constraints:
            obj['plane_constraints'] = list(plane_constraints)
        self.objects.append(obj)


def build_hangar_world():
    world = WorldBuilder()

    # The hangar spans x in [-65, 5] and y in [-30, 30]; its gabled roof peaks at z = 25.
    roof_slope = math.atan(0.3)
    vertical = math.pi / 2
    frame_x = (-10, -20, -30, -40, -50)  # x of the structural frames
    beam_radius = 0.4

    # Floor, walls and roof.
    world.add_plane(center=[0, 0, 0], angles=[0, 0, 0], description='Hangar main floor')
    for x in (5, -65):
        world.add_plane(center=[x, 0, 0], angles=[0, vertical, 0], description='Hangar wall')
    for y in (30, -30):
        world.add_plane(center=[0, y, 0], angles=[vertical, 0, 0], description='Hangar wall')
    for roll in (roof_slope, -roof_slope):
        world.add_plane(center=[0, 0, 25], angles=[roll, 0, 0], description='Hangar ceiling')

    # Rafters along both roof slopes.
    for x in frame_x:
        for roll in (vertical - roof_slope, -(vertical - roof_slope)):
            world.add_cylinder(center=[x, 0, 25], angles=[roll, 0, 0], radius=beam_radius,
                               description='Hangar ceiling structure')

    # Columns along the walls.
    for x in frame_x:
        for y in (30, -30):
            world.add_cylinder(center=[x, y, 0], angles=[0, 0, 0], radius=beam_radius,
                               description='Hangar vertical wall structure')
    for x in (5, -65):
        world.add_cylinder(center=[x, 0, 0], angles=[0, 0, 0], radius=beam_radius,
                           description='Hangar vertical wall structure')

    # Horizontal beams along the walls.
    for y, z in ((30, 7), (30, 14), (-30, 7), (-30, 17)):
        world.add_cylinder(center=[0, y, z], angles=[0, vertical, 0], radius=beam_radius,
                           description='Hangar horizontal wall structure')
    for x in (5, -65):
        for z in (7, 14):
            world.add_cylinder(center=[x, 0, z], angles=[vertical, 0, 0], radius=beam_radius,
                               description='Hangar horizontal wall structure')

    # Tie beams below the roof.
    world.add_cylinder(center=[0, 0, 19.25], angles=[0, vertical, 0], radius=beam_radius,
                       description='Hangar bottom ceiling structure')
    for x in frame_x:
        world.add_cylinder(center=[x, 0, 19.25], angles=[vertical, 0, 0], radius=beam_radius,
                           description='Hangar bottom ceiling structure')

    # Airplane, nose towards +x. Engines are the rear halves of ellipsoids, open towards the front.
    engine_size = [5.5, 1.6, 1.6]
    engine_rear_half = [constraint([-1, 0, 0], [0, 0, 0])]
    for center, side in (([-20, 8, 4.5], 'left internal'), ([-20, -8, 4.5], 'right internal'),
                         ([-23, 15, 4.5], 'left external'), ([-23, -15, 4.5], 'right external')):
        world.add_ellipsoid(center=center, size=engine_size, plane_constraints=engine_rear_half,
                            description=f'Airplane {side} engine')
    world.add_ellipsoid(center=[-30, 0, 5], size=[28, 4, 4], description='Airplane main fuselage')
    world.add_ellipsoid(center=[-25, 0, 6], size=[5, 25, 0.5], angles=[0, -0.1, 0.3],
                        plane_constraints=[constraint([0, 1, 0], [0, 0, 0])],
                        description='Airplane left main wing')
    world.add_ellipsoid(center=[-25, 0, 6], size=[5, 25, 0.5], angles=[0, -0.1, -0.3],
                        plane_constraints=[constraint([0, -1, 0], [0, 0, 0])],
                        description='Airplane right main wing')
    world.add_ellipsoid(center=[-52, 0, 11], size=[2.5, 0.5, 8], angles=[0, -0.4, 0],
                        plane_constraints=[constraint([0, 0, -1], [0, 0, 6.5])],
                        description='Airplane tail')
    world.add_ellipsoid(center=[-56, 0, 16], size=[4, 8, 0.6], angles=[0, -0.1, 0],
                        description='Airplane tail wing')

    # Test shapes for plane constraints.
    world.add_cylinder(
        center=[-5, 12, 9], angles=[1.57, 0, 0], radius=0.5,
        plane_constraints=[
            constraint([0, 0, 1], [0, 0, -1]),
            constraint([0, 0, -1], [0, 0, 5]),
            constraint([0, 1, -0.2], [0, -0.25, 0]),
        ],
        description='Cylinder with plane constraint')
    world.add_ellipsoid(
        center=[-5, 17, 9], size=[3, 2, 1], angles=[-0.5, 0, 0],
        plane_constraints=[constraint([-0.4, 0, 1], [0, 0, 0])],
        description='Ellipsoid with plane constraint')
    world.add_plane(
        center=[-1, 12, 9], angles=[0.5, vertical, 0],
        plane_constraints=[
            constraint([0, -1, 0], [0, 1, 0]),
            constraint([0, 1, 0], [0, -1, 0]),
            constraint([-1, 0, 0], [1, 0, 0]),
            constraint([1, 0, 0], [-1, 0, 0]),
        ],
        description='Plane with plane constraint')
    world.add_sphere(
        center=[1, 16, 9], radius=1.5,
        plane_constraints=[constraint([0, 0.4, 1], [0, 0, 0])],
        description='Sphere with plane constraint')
    # Upper nappe only, apex at the center, opening upward. Base radius is slope * height.
    world.add_cone(
        center=[-8, 22, 2], angles=[0, 0, 0], slope=0.5,
        plane_constraints=[
            constraint([0, 0, 1], [0, 0, 0]),
            constraint([0, 0, -1], [0, 0, 4]),
        ],
        description='Cone with plane constraint')

    return world


if __name__ == '__main__':
    script_dir = os.path.dirname(os.path.abspath(__file__))
    default_path = os.path.join(script_dir, '..', 'config', 'world.yaml')
    output_path = sys.argv[1] if len(sys.argv) > 1 else default_path
    build_hangar_world().save(output_path)
    print(f'Wrote {output_path}')
